#!/usr/bin/env node
"use strict";

const fs = require("fs");

const filePath = process.argv[2];

if (!filePath) {
  console.error("tcount: error: no file path provided");
  console.error("usage: node tcount.js <file>");
  process.exit(1);
}

let stats;
try {
  stats = fs.statSync(filePath);
} catch (err) {
  console.error(`tcount: error: cannot read "${filePath}": ${err.message}`);
  process.exit(1);
}

if (stats.isDirectory()) {
  console.error(`tcount: error: "${filePath}" is a directory, not a file`);
  process.exit(1);
}

const content = fs.readFileSync(filePath, "utf8");
const wordCount = content.split(/\s+/).filter((w) => w.length > 0).length;
console.log(wordCount);

