"use strict";

const test = require("node:test");
const assert = require("node:assert");
const { execFile } = require("node:child_process");
const fs = require("node:fs");
const os = require("node:os");
const path = require("node:path");

const CLI = path.join(__dirname, "tcount.js");

function runCli(args) {
  return new Promise((resolve) => {
    execFile(process.execPath, [CLI, ...args], (error, stdout, stderr) => {
      resolve({ code: error ? error.code : 0, stdout, stderr });
    });
  });
}

test("happy path: prints the number of whitespace-separated words", async () => {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), "tcount-test-"));
  const file = path.join(dir, "words.txt");
  fs.writeFileSync(file, "hello world\nfoo  bar\tbaz\n");
  try {
    const { code, stdout } = await runCli([file]);
    assert.strictEqual(code, 0);
    assert.strictEqual(stdout.trim(), "5");
  } finally {
    fs.rmSync(dir, { recursive: true, force: true });
  }
});

test("error path: missing file exits non-zero and prints to stderr", async () => {
  const missing = path.join(os.tmpdir(), "tcount-does-not-exist.txt");
  const { code, stdout, stderr } = await runCli([missing]);
  assert.notStrictEqual(code, 0);
  assert.strictEqual(stdout, "");
  assert.match(stderr, /error/i);
  assert.match(stderr, /missing|no such file|does not exist/i);
});

test("error path: directory exits non-zero and prints to stderr", async () => {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), "tcount-dir-"));
  try {
    const { code, stdout, stderr } = await runCli([dir]);
    assert.notStrictEqual(code, 0);
    assert.strictEqual(stdout, "");
    assert.match(stderr, /error/i);
    assert.match(stderr, /directory/i);
  } finally {
    fs.rmSync(dir, { recursive: true, force: true });
  }
});

